def is_heat_or_wave_noise(blob: str) -> bool:
    """Drop heat/wave questions that only matched because of OCR bleed words."""
    heat = any(
        k in blob
        for k in (
            "latent heat",
            "specific heat",
            "heat capacity",
            "melting point",
            "solidify",
            "vacuum flask",
            "electric heater",
            "joulemeter",
            "ice at",
            "kg of water",
            "kg of ice",
        )
    )
    nuclearish = any(
        k in blob
        for k in (
            "radioactiv",
            "nuclear",
            "nuclide",
            "alpha",
            "beta",
            "gamma",
            "half-life",
            "half life",
            "fission",
            "uranium",
            "deuterium",
        )
    )
    if heat and not nuclearish:
        return True
    wave = any(
        k in blob
        for k in (
            "diffraction grating",
            "microwave",
            "infra-red",
            "infrared",
            "ultra-violet",
            "ultraviolet",
            "wavelength",
            "spectral line",
            "sodium lamp",
        )
    )
    if wave and not nuclearish and "x-ray" not in blob and "x ray" not in blob:
        return True
    # Pure X-ray tube / wavelength questions are Atomic World / waves, not Ch.25 nuclear.
    if ("x-ray" in blob or "x ray" in blob) and not nuclearish and "ionizing radiation" not in blob and "ionising radiation" not in blob:
        return True
    if "photoelectric" in blob or "work function" in blob:
        return True
    return False


